function relevantTipIds(article){return [...new Set([...(article.tipIds||[]),...practicalTips.filter(tip=>(tip.topics||[]).some(topic=>(article.topics||[]).includes(topic))).map(tip=>tip.id)])];}
function renderPracticalTips(ids){return ids.map(id=>practicalTips.find(tip=>tip.id===id)).filter(Boolean).map(tip=>`<aside class="practical-tip" id="tip-${tip.id}"><h3>${tip.title}</h3>${(tip.paragraphs||[tip.text]).map(text=>`<p>${text}</p>`).join('')}</aside>`).join('');}
