function knowledgeTokens(value){return knowledgeNormalize(value).split(' ').filter(w=>w.length>1&&!knowledgeStop.has(w)).map(w=>w.length>4?w.replace(/(иями|ами|ого|ему|ыми|ий|ый|ой|ая|яя|ое|ые|ие|ов|ев|ом|ам|ах|ях|ется|ются|ить|ать|ять|ит|ет|ут|ют|а|я|ы|и|у|е)$/,''):w);}
function knowledgeTerms(token){const group=knowledgeSynonyms.find(g=>g.some(root=>token.startsWith(root)));return group||[token];}
const knowledgeIndex=knowledgeSearchItems.map(item=>({item,title:knowledgeNormalize(item.heading),tags:knowledgeNormalize((item.tags||[]).join(' ')+' '+item.keywords),body:knowledgeNormalize((item.summary||'')+' '+item.body)}));
function scoreKnowledge(query){const tokens=knowledgeTokens(query);if(!tokens.length)return query.trim()?[]:knowledgeIndex.map(x=>({...x,score:1}));const equipment=knowledgeSynonyms.slice(0,4).filter(g=>tokens.some(t=>g.some(root=>t.startsWith(root))));return knowledgeIndex.map(entry=>{const all=entry.title+' '+entry.tags+' '+entry.body;if(tokens.some(t=>['слаб','напор'].some(r=>t.startsWith(r)))&&!/слаб|напор/.test(entry.title+' '+entry.tags))return {...entry,score:0};if(equipment.some(g=>!g.some(root=>(entry.title+' '+entry.tags).includes(root))))return {...entry,score:0};let score=0,hits=0;for(const token of tokens){const terms=knowledgeTerms(token);const has=text=>terms.some(term=>text.includes(term));if(has(all)){hits++;score+=has(entry.title)?8:has(entry.tags)?5:1;}}return {...entry,score:hits>=Math.max(1,Math.ceil(tokens.length*.7))?score:0};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);}
function findKnowledge(query){return scoreKnowledge(query).map(x=>x.item);}
function initializeKnowledgeSearch(){const input=document.querySelector('#knowledge-search');if(!input)return;const result=document.querySelector('#knowledge-results'),status=document.querySelector('#knowledge-status');
const suggestions=document.createElement('div');suggestions.id='knowledge-suggestions';suggestions.className='knowledge-suggestions';suggestions.hidden=true;input.insertAdjacentElement('afterend',suggestions);input.setAttribute('aria-controls','knowledge-suggestions knowledge-results');
function suggest(matches){const active=input.value.trim().length>0;suggestions.hidden=!active;document.querySelector('.advice-page').classList.toggle('search-active',active);if(!active){suggestions.innerHTML='';return;}suggestions.innerHTML=matches.length?'<p class="suggestion-count">Найдено: '+matches.length+'. Нажмите на подсказку</p>'+matches.slice(0,5).map(a=>`<a class="knowledge-suggestion knowledge-${a.type}" href="${a.url}"><span class="knowledge-type">${knowledgeKinds[a.type].label}</span><strong>${escapeKnowledge(a.heading)}</strong><span aria-hidden="true">↗</span></a>`).join(''):'<p class="suggestion-count">Похожих материалов пока нет.</p><a class="suggestion-contact" href="/kontakty/">Написать мастеру ↗</a>';}
input.addEventListener('keydown',event=>{if(event.key==='ArrowDown'){const first=suggestions.querySelector('a');if(first){event.preventDefault();first.focus();}}if(event.key==='Escape'){suggestions.hidden=true;}if(event.key==='Enter'){const first=suggestions.querySelector('a');if(first&&!suggestions.hidden){event.preventDefault();first.click();}}});suggestions.addEventListener('keydown',event=>{const links=[...suggestions.querySelectorAll('a')],i=links.indexOf(document.activeElement);if(event.key==='ArrowDown'){event.preventDefault();links[Math.min(i+1,links.length-1)]?.focus();}if(event.key==='ArrowUp'){event.preventDefault();if(i<=0)input.focus();else links[i-1].focus();}if(event.key==='Escape'){input.focus();suggestions.hidden=true;}});
let selected='all';const render=()=>{const matches=findKnowledge(input.value).filter(a=>selected==='all'||a.type===selected);suggest(matches);status.textContent=matches.length?(input.value.trim()?'Подходящих материалов: ':'Материалов: ')+matches.length:'';if(matches.length){result.innerHTML=matches.map(knowledgeCard).join('');return;}const related=scoreKnowledge(input.value).slice(0,3).map(x=>x.item);if(!related.length){const subject=knowledgeTokens(input.value).find(t=>knowledgeSynonyms.slice(0,4).some(g=>g.some(r=>t.startsWith(r))));if(subject)related.push(...findKnowledge(subject).slice(0,3));}result.innerHTML=`<section class="knowledge-empty"><h2>Похожих материалов пока нет.</h2><p>${selected!=='all'?'Попробуйте выбрать «Все материалы» или описать проблему иначе.':'Попробуйте другие слова или напишите мастеру.'}</p><h3>${related.length?'Близкие темы':'Пока можно почитать'}</h3><div class="knowledge-topics">${(related.length?related:knowledgeSearchItems.slice(0,3)).map(a=>`<a href="${a.url}">${escapeKnowledge(a.heading)} ↗</a>`).join('')}</div><a class="button" href="/kontakty/">Написать мастеру ↗</a><p>Выберите доступный мессенджер в контактах: MAX, WhatsApp или Telegram.</p></section>`;};input.addEventListener('input',render);document.querySelectorAll('[data-query]').forEach(button=>button.addEventListener('click',()=>{input.value=button.dataset.query;selected='all';syncFilters();render();input.focus();}));function syncFilters(){document.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kind===selected)));}document.querySelectorAll('[data-kind]').forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.kind;syncFilters();render();}));render();}
